@extends('layouts.admin')
@section('content')
<div x-data="apkDocentesView()" x-init="init()" x-cloak>
    <div class="mb-6 flex flex-wrap items-start justify-between gap-4"><div><h1 class="page-title">APK Docentes</h1><p class="page-subtitle">Versiones firmadas y distribución pública controlada</p></div><a :href="urlPublica" target="_blank" class="btn btn-outline">Abrir URL pública</a></div>
    <div class="mb-4 rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-xs text-amber-800"><p class="font-semibold">Diagnóstico del servidor</p><template x-if="diagnostico.error"><p class="mt-1 rounded bg-red-50 px-2 py-1 text-red-700" x-text="diagnostico.error"></p></template><p>Ruta: <code x-text="diagnostico.carpeta_absoluta || diagnostico.ruta_absoluta"></code> · ¿Existe?: <span x-text="diagnostico.carpeta_existe === true ? 'Sí' : (diagnostico.carpeta_existe === false ? 'No' : '—')"></span></p><template x-if="diagnostico.lista_vieja"><div class="mt-1"><p class="font-semibold">Carpeta vieja storage/app/apk-docentes:</p><p x-text="diagnostico.lista_vieja.existe ? 'Existe (' + diagnostico.lista_vieja.archivos.length + ' archivos)' : 'No existe'"></p><template x-if="diagnostico.lista_vieja.archivos.length"><ul><template x-for="a in diagnostico.lista_vieja.archivos" :key="a.ruta"><li class="break-all" x-text="a.ruta + ' — ' + Math.round(a.tamano/1024/1024) + ' MB'"></li></template></ul></template></div></template><p class="mt-1" x-show="diagnostico.lista_objetiva"><span class="font-semibold">Carpeta objetivo (private/apk-docentes):</span> <span x-text="diagnostico.lista_objetiva?.existe ? 'Existe (' + diagnostico.lista_objetiva.archivos.length + ' archivos)' : 'No existe'"></span></p><template x-if="diagnostico.lista_objetiva && diagnostico.lista_objetiva.archivos.length"><ul><template x-for="a in diagnostico.lista_objetiva.archivos" :key="a.ruta"><li class="break-all" x-text="a.ruta + ' — ' + Math.round(a.tamano/1024/1024) + ' MB'"></li></template></ul></template><template x-if="diagnostico.archivos.length === 0 && !diagnostico.error"><p>Sin archivos en la carpeta.</p></template><template x-if="diagnostico.archivos.length > 0"><div><p class="mt-1 font-semibold">Archivos encontrados:</p><ul><template x-for="a in diagnostico.archivos" :key="a.ruta"><li x-text="a.ruta + ' — ' + Math.round(a.tamano/1024/1024) + ' MB — ' + a.modificado"></li></template></ul></div></template></div>
    <div class="card mb-6" x-show="api.hasPermission('distribucion_apk.crear')"><div class="card-body"><h2 class="font-semibold text-gray-900">Registrar nueva versión</h2><p class="mt-1 text-sm text-gray-500">El archivo se guarda fuera de la carpeta pública. Solo una versión publicada será descargable desde la URL pública.</p><div class="mt-4 flex flex-wrap gap-3"><label class="flex items-center gap-2 text-sm font-medium text-gray-700"><input x-model="desdeServidor" type="checkbox"> Registrar desde un APK ya colocado en <code class="text-xs" x-text="rutaStorage"></code> (por FTP)</label></div><form class="mt-5 grid grid-cols-1 gap-4 md:grid-cols-2" @submit.prevent="subir()"><div><label class="label">Versión *</label><input x-model="form.version" required maxlength="40" class="input" placeholder="1.0.0"></div><div><label class="label">Version code Android *</label><input x-model.number="form.version_code" required min="1" type="number" class="input" placeholder="1"></div><template x-if="!desdeServidor"><div class="md:col-span-2"><label class="label">APK firmada *</label><input @change="form.archivo = $event.target.files[0]" required type="file" accept=".apk,application/vnd.android.package-archive" class="input"></div></template><template x-if="desdeServidor"><div class="md:col-span-2 rounded-lg border border-brand-200 bg-brand-50 px-4 py-3 text-sm text-brand-800">Se registrará el APK más reciente encontrado en <code class="text-xs" x-text="rutaStorage"></code>. No se subirá ningún archivo.</div></template><div class="md:col-span-2"><label class="label">Notas de versión</label><textarea x-model="form.notas_version" class="input" rows="3" placeholder="Cambios incluidos en esta versión"></textarea></div><label class="flex items-center gap-2 text-sm font-medium text-gray-700 md:col-span-2"><input x-model="form.publicar" type="checkbox"> Publicar ahora como versión disponible</label><div class="md:col-span-2"><button :disabled="subiendo" class="btn btn-primary"><span x-text="subiendo ? 'Registrando...' : 'Registrar APK'"></span></button></div></form></div></div>
    <template x-if="loading"><div class="py-12 text-center text-gray-500">Cargando versiones...</div></template><div class="card" x-show="!loading"><div class="table-container"><table class="table"><thead><tr><th>Versión</th><th>Archivo</th><th>Hash SHA-256</th><th>Estado</th><th>Publicado</th><th></th></tr></thead><tbody><template x-for="item in publicaciones" :key="item.id"><tr><td><span class="font-semibold" x-text="item.version"></span><span class="block text-xs text-gray-500" x-text="'Código ' + item.version_code"></span></td><td class="text-sm" x-text="item.nombre_archivo"></td><td class="max-w-48 truncate font-mono text-xs" :title="item.sha256" x-text="item.sha256"></td><td><span class="badge" :class="item.publicado ? 'badge-success' : 'badge-info'" x-text="item.publicado ? 'Publicada' : 'Borrador'"></span></td><td class="text-sm" x-text="item.publicado_en || '-'"></td><td class="text-right"><button x-show="!item.publicado && api.hasPermission('distribucion_apk.modificar')" @click="publicar(item)" class="btn btn-ghost btn-sm text-brand-700">Publicar</button></td></tr></template><tr x-show="publicaciones.length === 0"><td colspan="6" class="py-8 text-center text-gray-400">Aún no se han registrado APK.</td></tr></tbody></table></div></div>
</div>
@endsection
@section('scripts')
<script>
function apkDocentesView() { return { loading:true, subiendo:false, error:'', publicaciones:[], urlPublica:'/apk/docentes', rutaStorage:'storage/app/apk-docentes/', diagnostico:{carpeta_absoluta:'',carpeta_existe:false,archivos:[]}, desdeServidor:false, form:{version:'',version_code:'',archivo:null,notas_version:'',publicar:false}, token(){return localStorage.getItem('auth-token')||localStorage.getItem('auth_token')}, async init(){try{const {data}=await window.axios.get('/api/v1/distribucion-apk/docentes',{headers:{Authorization:`Bearer ${this.token()}`}});this.publicaciones=data.data||[];this.urlPublica=data.url_publica||this.urlPublica;this.rutaStorage=data.ruta_storage||this.rutaStorage;this.diagnostico=data.diagnostico||this.diagnostico;if(data.error_diagnostico)this.error=data.error_diagnostico}catch(e){this.error=(e.response&&e.response.data&&e.response.data.error_diagnostico)||window.extractError(e,'No se pudieron cargar las publicaciones APK')}finally{this.loading=false}}, async subir(){this.subiendo=true;this.error='';try{const deServidor=this.desdeServidor;const datos=new FormData();datos.append('desde_servidor',deServidor?'1':'0');Object.entries(this.form).forEach(([k,v])=>{if(k==='publicar')datos.append(k,v?'1':'0');else if(k==='archivo'){if(!deServidor&&v!==null)datos.append(k,v)}else if(v!==null)datos.append(k,v)});await window.axios.post('/api/v1/distribucion-apk/docentes',datos,{headers:{Authorization:`Bearer ${this.token()}`}});this.form={version:'',version_code:'',archivo:null,notas_version:'',publicar:false};await this.init()}catch(e){this.error=window.extractError(e,'No se pudo registrar el APK')}finally{this.subiendo=false}}, async publicar(item){if(!confirm(`¿Publicar la versión ${item.version}? Reemplazará la versión pública actual.`))return;try{await window.axios.post(`/api/v1/distribucion-apk/docentes/${item.id}/publicar`,{},{headers:{Authorization:`Bearer ${this.token()}`}});await this.init()}catch(e){this.error=window.extractError(e,'No se pudo publicar el APK')}} } }
</script>
@endsection
